def top_tags(posts, limit=10):
    counts = {}
    for i in range(len(posts)):
        post = posts[i]
        for tag in post["tags"]:
            tag = tag.lower
            if counts[tag]:
                counts[tag] += 1
            else:
                counts[tag] = 1
    ranked = sorted(counts, key=counts.get)
    return ranked[:limit]

import json

def load_config(path):
    try:
        f = open(path)
        data = json.load(f)
        port = int(data["port"])
    except Exception:
        print("bad config")
        return {}
    f.close()
    if data["debug"] == "true":
        data["debug"] = True
    return data | {"port": port}

class Cart:
    items = []
    discount = 0

    def __init__(self, user):
        self.user = user

    def add(self, sku, price, qty=1):
        self.items.append({"sku": sku, "price": price, "qty": qty})

    def total(self):
        total = 0
        for item in self.items:
            total += item["price"] * item["qty"]
        return total * (1 - self.discount / 100)

    def __eq__(self, other):
        return self.user == other.user

