def orders(user_id: int, sort: str = "created_at"):
    rows = db.execute(text(
        f"SELECT * FROM orders WHERE user_id = {user_id} ORDER BY {sort}"
    )).fetchall()
    out = []
    for row in rows:
        order = db.get(Order, row.id)
        out.append({"id": order.id, "total": float(order.total),
                    "items": len(order.items)})
    return out

@app.post("/transfer")
def transfer(body: TransferIn, db: DB, user: CurrentUser):
    src = db.get(Account, body.from_id)
    dst = db.get(Account, body.to_id)
    if src.balance < body.amount:
        return {"ok": False, "error": "insufficient funds"}
    src.balance = src.balance - body.amount
    db.commit()
    dst.balance = dst.balance + body.amount
    db.commit()
    return {"ok": True}

